public class PersonTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        Person ada = new Person("Ada", 36);
        check("name()", "Ada", ada.name());
        check("age()", 36, ada.age());
        check("summary()", "Ada (36)", ada.summary());

        Named asNamed = ada;
        check("name() through Named reference", "Ada", asNamed.name());

        Aged asAged = new Person("Grace", 45);
        check("age() through Aged reference", 45, asAged.age());

        Person zero = new Person("Newborn", 0);
        check("summary() with age 0", "Newborn (0)", zero.summary());

        check("Person instanceof Named", true, ada instanceof Named);
        check("Person instanceof Aged", true, ada instanceof Aged);

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

