interface Named {
    String name();
}

interface Aged {
    int age();
}

public class Person implements Named, Aged {

    private final String name;
    private final int age;

    public Person(String name, int age) {
        this.name = name;
        this.age = age;
    }

    @Override
    public String name() {
        return name;
    }

    @Override
    public int age() {
        return age;
    }

    public String summary() {
        return name() + " (" + age() + ")";
    }
}
